// ─────────────────────────────────────────────────────────────────────────────
//  data/suwar.ts  --  All 114 Surahs of the Holy Quran
// ─────────────────────────────────────────────────────────────────────────────

export interface Surah {
  id: number;
  arabic: string;           // Full Arabic name with article
  transliteration: string;  // Romanised name
  english: string;          // English meaning
  verses: number;           // Number of ayat
  revelation: 'Meccan' | 'Medinan';
  juz: number;              // Primary juz (1–30)
  category: SurahCategory;
  openingVerse: string;     // First few words in Arabic
  openingTrans: string;     // English of opening verse
  reflection: string;       // Meditative reflection text
  virtue?: string;          // Hadith or classical virtue / fadl
}

export type SurahCategory =
  | 'tawhid'       // Monotheism & Divine attributes
  | 'prophethood'  // Stories of Prophets
  | 'law'          // Legislation & community life
  | 'eschatology'  // Afterlife, Day of Judgement
  | 'mercy'        // Divine mercy & forgiveness
  | 'wisdom'       // Wisdom, ethics & reflection
  | 'creation'     // Creation & cosmos
  | 'devotion';    // Prayer, remembrance & spiritual stations

export const SURAH_CATEGORY_LABELS: Record<SurahCategory, string> = {
  tawhid:       'Tawḥīd & Divine Names',
  prophethood:  'Stories of Prophets',
  law:          'Law & Community',
  eschatology:  'Ākhira & Judgement',
  mercy:        'Divine Mercy',
  wisdom:       'Wisdom & Ethics',
  creation:     'Creation & Cosmos',
  devotion:     'Devotion & Prayer',
};

