// ── Helpers ────────────────────────────────────────────────────────────────────

export const REVELATION_COLORS: Record<'Meccan' | 'Medinan', string> = {
  Meccan:  '#7C3AED',
  Medinan: '#059669',
};

export const ALL_SURAH_CATEGORIES: SurahCategory[] = [
  'tawhid', 'prophethood', 'law', 'eschatology',
  'mercy', 'wisdom', 'creation', 'devotion',
];

export function getSurahsByJuz(juz: number): Surah[] {
  return suwar.filter(s => s.juz === juz);
}

export function getSurahsByCategory(cat: SurahCategory): Surah[] {
  return suwar.filter(s => s.category === cat);
}

